from qgis.core import (QgsVectorLayer, QgsCoordinateTransform, QgsSpatialIndex,
                        QgsGeometry, QgsField)
from qgis.PyQt.QtCore import QVariant

def find(keyword):
    return [l for l in project.mapLayers().values()
            if isinstance(l, QgsVectorLayer) and keyword in l.name().lower() and l.featureCount() > 0]

dvf = find('dvf')
bands = find('bande')

if not dvf:
    result['error'] = 'Couche DVF non trouvee'
elif not bands:
    result['warning'] = 'Pas de bandes cotieres. Assignation ignoree.'
    result['success'] = True
else:
    dvf_layer = dvf[0]
    bands_layer = bands[0]

    dvf_layer.startEditing()
    if dvf_layer.fields().indexOf('coastal_band') < 0:
        dvf_layer.addAttribute(QgsField('coastal_band', QVariant.String))
    if dvf_layer.fields().indexOf('band_id') < 0:
        dvf_layer.addAttribute(QgsField('band_id', QVariant.Int))
    dvf_layer.updateFields()

    band_idx = QgsSpatialIndex(bands_layer.getFeatures())
    band_features = {f.id(): f for f in bands_layer.getFeatures()}
    tr = QgsCoordinateTransform(dvf_layer.crs(), bands_layer.crs(), project)

    cb_idx = dvf_layer.fields().indexOf('coastal_band')
    bi_idx = dvf_layer.fields().indexOf('band_id')

    stats = {}
    for feat in dvf_layer.getFeatures():
        geom = QgsGeometry(feat.geometry())
        geom.transform(tr)
        year = feat['year']
        pm2 = feat['price_m2']
        assigned_band = 'Hors bande'
        assigned_id = 0
        candidates = band_idx.intersects(geom.boundingBox())
        for cid in candidates:
            if cid in band_features and geom.within(band_features[cid].geometry()):
                assigned_band = band_features[cid]['band_label']
                assigned_id = band_features[cid]['band_id']
                break
        dvf_layer.changeAttributeValue(feat.id(), cb_idx, assigned_band)
        dvf_layer.changeAttributeValue(feat.id(), bi_idx, assigned_id)
        if year not in stats:
            stats[year] = {}
        if assigned_band not in stats[year]:
            stats[year][assigned_band] = []
        stats[year][assigned_band].append(pm2)

    dvf_layer.commitChanges()

    summary = {}
    for year, bands_data in sorted(stats.items()):
        ys = {}
        for band, prices in bands_data.items():
            ps = sorted(prices)
            n = len(ps)
            ys[band] = {
                'count': n,
                'median_m2': round(ps[n // 2], 0) if n else 0,
                'mean_m2': round(sum(prices) / n, 0) if n else 0
            }
        summary[str(year)] = ys
    result['stats_by_year_band'] = summary
    result['success'] = True
